def _stresses(split, calibration):
    gain, bias = calibration[np.asarray(split['lab_id'], dtype=int)].T
    return (gain[:, None] * split['past_stress_cmd'] + bias[:, None], gain * split['stress_hold_cmd'] + bias, np.asarray(split['initial_memory_states']))

def _design(tau, stress, dt, t, x, yield_stress, plastic):
    past, hold, memory = stress
    tail = np.r_[np.cumsum(dt[:0:-1])[::-1], 0.0]
    kernel = np.exp(-tail[:, None] / tau) * -np.expm1(-dt[:, None] / tau)
    delta = hold[:, None] - past @ kernel - memory * np.exp(-dt.sum() / tau)
    if plastic:
        excess = np.maximum(hold - yield_stress, 0.0)
        x = np.column_stack((x, excess, excess ** 2))
    curve = np.concatenate((delta[:, None, :] * -np.expm1(-t[:, None] / tau), x[:, None, :] * t[None, :, None]), axis=2)
    return (curve, np.column_stack((delta / tau, x)))

def _load_calibration(checks, *, return_identified=False):
    gain, bias = (np.ones(4), np.zeros(4))
    lab = np.asarray(checks['lab_id'])
    cmd, true = map(np.asarray, (checks['cmd_stress'], checks['true_stress']))
    pooled = []
    for j in range(4):
        m = (lab == j) & np.isfinite(cmd) & np.isfinite(true)
        x, y = (cmd[m], true[m])
        if len(x) < 2 or np.ptp(x) < 1e-08:
            continue
        i, k = np.triu_indices(len(x), 1)
        spread = abs(x[k] - x[i]) > max(1e-08, 0.05 * np.ptp(x))
        i, k = (i[spread], k[spread])
        slopes = (y[k] - y[i]) / (x[k] - x[i])
        a = np.median(slopes)
        b = np.median(y - a * x)
        e = y - a * x - b
        m = abs(e) <= max(0.001, 5 * 1.4826 * np.median(abs(e)))
        if m.sum() >= 2 and np.ptp(x[m]) > 1e-08:
            gain[j], bias[j] = np.linalg.lstsq(np.column_stack((x[m], np.ones(m.sum()))), y[m], rcond=None)[0]
            pooled.append(j)
    for j in set(range(4)) - set(pooled):
        peer = j ^ 1
        if peer in pooled:
            gain[j], bias[j] = (gain[peer], bias[peer])
        m = (lab == j) & np.isfinite(cmd) & np.isfinite(true)
        if m.any():
            bias[j] = np.median(true[m] - gain[j] * cmd[m])
    if return_identified:
        return (gain, bias, np.isin(np.arange(4), pooled))
    return (gain, bias)
